-- Sales Representatives with Above-Average Sales
-- The Sales Management team wants to identify sales representatives whose total sales revenue is higher than the average revenue generated by all sales 
-- representatives. This will help management assess individual sales performance.
-- Display the sales representative ID and total sales revenue for sales representatives whose total sales revenue is above the average sales revenue.
-- Tables:Sales_SalesOrderHeader.


SELECT
    SalesPersonID,
    SUM(SubTotal) AS TotalSalesRevenue
FROM Sales_SalesOrderHeader
WHERE SalesPersonID IS NOT NULL
GROUP BY SalesPersonID
HAVING SUM(SubTotal) > (
    SELECT AVG(TotalRevenue)
    FROM (
        SELECT
            SalesPersonID,
            SUM(SubTotal) AS TotalRevenue
        FROM Sales_SalesOrderHeader
        WHERE SalesPersonID IS NOT NULL
        GROUP BY SalesPersonID
    ) AS AverageSales
)
ORDER BY TotalSalesRevenue DESC;
